#include <iostream>
using namespace std;

void addTenCopy(int number) {
    number = number + 10;           // changes the copy only
}

void addTenReal(int& number) {
    number = number + 10;           // changes the caller's variable
}

int main() {
    int score = 50;
    addTenCopy(score);
    cout << "After addTenCopy: " << score << endl;
    addTenReal(score);
    cout << "After addTenReal: " << score << endl;
    return 0;
}

