#include <iostream>
using namespace std;

void divide(int a, int b, int& quotient, int& remainder) {
    quotient = a / b;
    remainder = a % b;
}

int main() {
    int q;
    int r;

    divide(17, 5, q, r);
    cout << "17 / 5 is " << q << " remainder " << r << endl;

    divide(100, 7, q, r);
    cout << "100 / 7 is " << q << " remainder " << r << endl;
    return 0;
}

#include <iostream>
using namespace std;

void recordScore(int score, int& total, int& best) {
    total += score;
    if (score > best) {
        best = score;
    }
}

int main() {
    int total = 0;
    int best = 0;

    recordScore(70, total, best);
    recordScore(92, total, best);
    recordScore(85, total, best);

    cout << "Total: " << total << endl;
    cout << "Best: " << best << endl;
    return 0;
}

